const IMAGE_EXT = ["jpg","jpeg","png","gif","webp","avif","heic"];
const VIDEO_EXT = ["mp4","webm","mov","m4v"];
const AUDIO_EXT = ["mp3","m4a","wav","ogg"];

/**
 * Tries to discover files inside a folder two ways:
 * 1) Parsing a real directory listing (works when the site is served by
 *    something that auto-generates an index, e.g. `python3 -m http.server`,
 *    Apache/nginx autoindex, etc). This means dropping a file in the folder
 *    shows up with zero extra steps.
 * 2) Falling back to a manifest.json file in that folder (generated by
 *    generate_manifest.py) for hosts that don't provide directory listings
 *    (Netlify, GitHub Pages, S3 without listing, etc).
 */
async function discoverFiles(folder, extensions) {
  // Attempt 1: real directory listing
  try {
    const res = await fetch(folder + "/", { cache: "no-store" });
    if (res.ok) {
      const html = await res.text();
      const doc = new DOMParser().parseFromString(html, "text/html");
      const hrefs = Array.from(doc.querySelectorAll("a"))
        .map((a) => a.getAttribute("href"))
        .filter(Boolean)
        .map((h) => decodeURIComponent(h.split("?")[0]))
        .map((h) => h.replace(/^\.?\//, ""))
        .filter((h) => !h.includes("/") && !h.startsWith("."));

      const matches = hrefs.filter((h) =>
        extensions.some((ext) => h.toLowerCase().endsWith("." + ext))
      );
      if (matches.length) {
        return matches.sort().map((f) => `${folder}/${f}`);
      }
    }
  } catch (e) {
    /* no listing available, fall through to manifest */
  }

  // Attempt 2: manifest.json fallback
  try {
    const res = await fetch(`${folder}/manifest.json`, { cache: "no-store" });
    if (res.ok) {
      const list = await res.json();
      if (Array.isArray(list) && list.length) {
        return list.map((f) => `${folder}/${f}`);
      }
    }
  } catch (e) {
    /* nothing found */
  }

  return [];
}

function extOf(path) {
  return path.split(".").pop().toLowerCase();
}

function buildSlide(path) {
  const slide = document.createElement("div");
  slide.className = "slide";

  const box = document.createElement("div");
  box.className = "media-box";

  const ext = extOf(path);
  let mediaEl;
  if (VIDEO_EXT.includes(ext)) {
    mediaEl = document.createElement("video");
    mediaEl.src = path;
    mediaEl.muted = true;
    mediaEl.loop = true;
    mediaEl.playsInline = true;
    mediaEl.controls = true;
    mediaEl.preload = "metadata";
  } else {
    mediaEl = document.createElement("img");
    mediaEl.src = path;
    mediaEl.alt = "";
    mediaEl.loading = "lazy";
  }
  box.appendChild(mediaEl);
  slide.appendChild(box);
  return { slide, mediaEl, isVideo: VIDEO_EXT.includes(ext) };
}

async function initCarousel() {
  const track = document.getElementById("track");
  const emptyState = document.getElementById("emptyState");
  const dotsWrap = document.getElementById("dots");
  const prevBtn = document.getElementById("prevBtn");
  const nextBtn = document.getElementById("nextBtn");

  const files = await discoverFiles("images_and_videos", [...IMAGE_EXT, ...VIDEO_EXT]);

  if (!files.length) return; // keep the empty-state message

  emptyState.remove();

  const slides = files.map(buildSlide);
  slides.forEach(({ slide }) => track.appendChild(slide));

  // dots
  const dots = slides.map((_, i) => {
    const b = document.createElement("button");
    b.setAttribute("aria-label", `Ir para o slide ${i + 1}`);
    b.addEventListener("click", () => goTo(i));
    dotsWrap.appendChild(b);
    return b;
  });

  let current = 0;
  function goTo(i) {
    current = (i + slides.length) % slides.length;
    slides[current].slide.scrollIntoView({ behavior: "smooth", inline: "center", block: "nearest" });
  }
  prevBtn.addEventListener("click", () => { goTo(current - 1); resetAuto(); });
  nextBtn.addEventListener("click", () => { goTo(current + 1); resetAuto(); });

  // sync active dot + play/pause videos based on visibility
  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        const idx = slides.findIndex((s) => s.slide === entry.target);
        if (idx === -1) return;
        if (entry.isIntersecting && entry.intersectionRatio > 0.6) {
          current = idx;
          dots.forEach((d, i) => d.classList.toggle("active", i === idx));
          if (slides[idx].isVideo) slides[idx].mediaEl.play().catch(() => {});
        } else if (slides[idx].isVideo) {
          slides[idx].mediaEl.pause();
        }
      });
    },
    { root: track, threshold: [0, 0.6] }
  );
  slides.forEach(({ slide }) => observer.observe(slide));
  if (dots[0]) dots[0].classList.add("active");

  // gentle autoplay through the filmstrip
  let autoTimer = null;
  let paused = false;
  function startAuto() {
    autoTimer = setInterval(() => {
      if (!paused) goTo(current + 1);
    }, 4500);
  }
  function resetAuto() {
    clearInterval(autoTimer);
    startAuto();
  }
  track.addEventListener("mouseenter", () => (paused = true));
  track.addEventListener("mouseleave", () => (paused = false));
  track.addEventListener("touchstart", () => (paused = true), { passive: true });
  track.addEventListener("touchend", () => setTimeout(() => (paused = false), 3000), { passive: true });
  startAuto();
}

async function initAudio() {
  const files = await discoverFiles("audio", AUDIO_EXT);
  if (!files.length) return;

  const player = document.getElementById("audioPlayer");
  const audioEl = document.getElementById("bgAudio");
  const toggleBtn = document.getElementById("playToggle");
  const iconPlay = document.getElementById("iconPlay");
  const iconPause = document.getElementById("iconPause");

  audioEl.src = files[0];
  player.hidden = false;

  let playing = false;
  function setPlaying(state) {
    playing = state;
    iconPlay.style.display = state ? "none" : "block";
    iconPause.style.display = state ? "block" : "none";
    toggleBtn.setAttribute("aria-label", state ? "Pausar música de fundo" : "Tocar música de fundo");
  }

  toggleBtn.addEventListener("click", async () => {
    if (playing) {
      audioEl.pause();
      setPlaying(false);
    } else {
      try {
        await audioEl.play();
        setPlaying(true);
      } catch (e) {
        /* browser blocked playback; user can try again */
      }
    }
  });

  // Try to start softly on first user interaction anywhere on the page,
  // since browsers block audio autoplay until the person interacts.
  const tryAutoStart = async () => {
    if (playing) return;
    try {
      await audioEl.play();
      setPlaying(true);
    } catch (e) {
      /* ignore, wait for explicit button press */
    }
    document.removeEventListener("click", tryAutoStart);
  };
  document.addEventListener("click", tryAutoStart, { once: true });
}

function initLetterReveal() {
  const paragraphs = document.querySelectorAll(".letter p");
  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("visible");
          observer.unobserve(entry.target);
        }
      });
    },
    { threshold: 0.2 }
  );
  paragraphs.forEach((p) => observer.observe(p));
}

initCarousel();
initAudio();
initLetterReveal();
